function longestCappedStretch(nums: number[], k: number): number {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    const count = new Map<number, number>();
    let j = i;
    for (; j < nums.length; j++) {
      const c = (count.get(nums[j]) || 0) + 1;
      if (c > k) break;
      count.set(nums[j], c);
    }
    best = Math.max(best, j - i);
  }
  return best;
}

